package com.skyclone.mod.alchemy;

import com.google.gson.Gson;

import java.io.Reader;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The alchemy data table ({@code data/alchemy/effects.json}, generated by
 * {@code tools/gen/alchemy/gen_alchemy.py} from the NEU item files). PURE: no Bukkit, so unit tests
 * run the shipping numbers.
 */
public final class EffectTable {

    /** One level of one effect. {@code stats} are Stat enum names; {@code params} are effect-specific numbers. */
    public static final class Level {
        public int level;
        public String rarity = "COMMON";
        /** Base duration in seconds before modifiers and bonuses; 0 = instant. */
        public int seconds;
        public String desc = "";
        public Map<String, Double> stats = new LinkedHashMap<>();
        public Map<String, Double> params = new LinkedHashMap<>();

        public double param(String key) { Double v = params == null ? null : params.get(key); return v == null ? 0 : v; }
        public double stat(String key) { Double v = stats == null ? null : stats.get(key); return v == null ? 0 : v; }
    }

    public static final class Effect {
        public String id;
        public String name;
        /** Colour code of the "Name IV (3:00)" line. */
        public String line = "&9";
        public String color;
        /** buff | debuff | instant | xp | special */
        public String kind = "buff";
        public boolean extendable = true;
        public String corruptsTo;
        public String vanilla;
        public boolean brewable;
        public int brewMax;
        /** Sold only as a splash potion (its POTION_ id is thrown): Chilled Spirit Water, Gravity. */
        public boolean splashOnly;
        /**
         * The active LEVEL is the size of the effect: every stat of level row 1 is multiplied by it
         * (Midnight Wit: level 120 = +120 Intelligence). Labels read "Name +120" instead of a numeral.
         */
        public boolean scaled;
        /** The item that gives this effect when it is not a {@code POTION_<ID>;<L>} potion (Dread Draught...). */
        public String potionItem;
        public List<Level> levels = new ArrayList<>();

        /** Item id of this effect's level-{@code lvl} potion. */
        public String itemId(int lvl) { return potionItem != null ? potionItem : potionId(id, lvl, false); }

        public Level level(int n) {
            for (Level l : levels) if (l.level == n) return l;
            return null;
        }

        public int maxLevel() {
            int m = 0;
            for (Level l : levels) m = Math.max(m, l.level);
            return m;
        }

        public int minLevel() {
            int m = Integer.MAX_VALUE;
            for (Level l : levels) m = Math.min(m, l.level);
            return m == Integer.MAX_VALUE ? 0 : m;
        }

        /** The level at or below {@code n} that exists (sparse tables such as the herald potion). */
        public Level levelAtMost(int n) {
            Level best = null;
            for (Level l : levels) if (l.level <= n && (best == null || l.level > best.level)) best = l;
            return best != null ? best : (levels.isEmpty() ? null : levels.get(0));
        }

        public boolean isDebuff() { return "debuff".equals(kind); }
        public boolean isInstant() { return "instant".equals(kind); }

        /** "&9Speed V" (a scaled effect: "&bMidnight Wit +120"). */
        public String label(int lvl) { return line + name + " " + (scaled ? "+" + lvl : roman(lvl)); }

        /** Multiplier on level row values for an active level (1 unless {@link #scaled}). */
        public double scale(int lvl) { return scaled ? Math.max(0, lvl) : 1; }
    }

    public static final class Ingredient {
        public String item;
        public String effect;
        public int level = 1;
        public double xp;
        public String unlock;
        /** AWKWARD (default) or WATER. */
        public String base = "AWKWARD";
        public boolean tune;
    }

    public static final class Modifier {
        public String item;
        /** AWKWARD, LEVEL, DURATION, BOTH, SPLASH, CORRUPT */
        public String type;
        /** LEVEL: levels; DURATION/BOTH: seconds; SPLASH: tier (1 gunpowder, 2 enchanted). */
        public int amount;
        /** BOTH only: levels added. */
        public int levels;
        public double xp;
    }

    public static final class Bundle {
        public int level;
        public String rarity = "COMMON";
        public int seconds;
        public Map<String, Integer> effects = new LinkedHashMap<>();
    }

    /**
     * A Basic Brew (Cheap Coffee, Tepid Green Tea...): goes in a bottle slot instead of an Awkward
     * Potion, brews only the potions it can boost, and the potion it makes carries the bonus.
     * {@code flat}/{@code pct} keys are Stat enum names (stats) or param names (heal_per_sec, exp...).
     */
    public static final class BasicBrew {
        public String item;
        public String name;
        public Map<String, Double> flat = new LinkedHashMap<>();
        public Map<String, Double> pct = new LinkedHashMap<>();
        /** When set, the only effects it brews; otherwise every effect whose numbers it boosts. */
        public List<String> effects;
        public String desc = "";

        private double flat(String k) { Double v = flat == null ? null : flat.get(k); return v == null ? 0 : v; }
        private double pct(String k) { Double v = pct == null ? null : pct.get(k); return v == null ? 0 : v; }

        /** Does this brew make (and boost) potions of this effect? */
        public boolean appliesTo(Effect e) {
            if (e == null || e.levels.isEmpty()) return false;
            if (effects != null && !effects.isEmpty()) return effects.contains(e.id);
            for (Level l : e.levels) {
                if (flat != null) for (String k : flat.keySet()) if (l.stat(k) > 0 || l.param(k) > 0) return true;
                if (pct != null) for (String k : pct.keySet()) if (l.stat(k) > 0 || l.param(k) > 0) return true;
            }
            return false;
        }

        /** One stat or param value of a brewed potion: (value + flat) x (1 + pct%). Never touches a negative value. */
        public double apply(String key, double value) {
            if (value < 0) return value;
            double v = value + flat(key);
            double p = pct(key);
            return p != 0 && v > 0 ? v * (1 + p / 100.0) : v;
        }
    }

    /** The raw JSON shape. */
    public static final class Raw {
        public List<Effect> effects = new ArrayList<>();
        public List<Ingredient> ingredients = new ArrayList<>();
        public List<Modifier> modifiers = new ArrayList<>();
        public Map<String, Integer> god = new LinkedHashMap<>();
        public Map<String, List<Bundle>> bundles = new LinkedHashMap<>();
        public List<BasicBrew> brews = new ArrayList<>();
    }

    private final Map<String, Effect> effects = new LinkedHashMap<>();
    private final List<Ingredient> ingredients;
    private final Map<String, Modifier> modifiers = new LinkedHashMap<>();
    private final Map<String, Integer> god;
    private final Map<String, List<Bundle>> bundles;
    private final Map<String, BasicBrew> brews = new LinkedHashMap<>();

    private EffectTable(Raw raw) {
        if (raw.brews != null) for (BasicBrew b : raw.brews) if (b != null && b.item != null) brews.put(b.item, b);
        for (Effect e : raw.effects) effects.put(e.id, e);
        ingredients = raw.ingredients == null ? List.of() : List.copyOf(raw.ingredients);
        if (raw.modifiers != null) for (Modifier m : raw.modifiers) modifiers.put(m.item, m);
        god = raw.god == null ? Map.of() : Collections.unmodifiableMap(new LinkedHashMap<>(raw.god));
        bundles = raw.bundles == null ? Map.of() : raw.bundles;
    }

    public static EffectTable load(Reader in) {
        Raw raw = new Gson().fromJson(in, Raw.class);
        if (raw == null) raw = new Raw();
        return new EffectTable(raw);
    }

    public Effect effect(String id) { return id == null ? null : effects.get(id); }
    public Collection<Effect> effects() { return Collections.unmodifiableCollection(effects.values()); }
    public List<Ingredient> ingredients() { return ingredients; }
    public Collection<Modifier> modifiers() { return Collections.unmodifiableCollection(modifiers.values()); }
    public Modifier modifier(String item) { return item == null ? null : modifiers.get(item); }
    public Map<String, Integer> god() { return god; }
    public BasicBrew brew(String item) { return item == null ? null : brews.get(item); }
    public Collection<BasicBrew> brews() { return Collections.unmodifiableCollection(brews.values()); }

    /** Brewable effects a Basic Brew can make (for the guide and messages). */
    public List<Effect> brewsInto(BasicBrew b) {
        List<Effect> out = new ArrayList<>();
        if (b != null) for (Effect e : effects.values()) if (e.brewable && b.appliesTo(e)) out.add(e);
        return out;
    }
    public List<Bundle> bundles(String kind) { List<Bundle> b = bundles.get(kind); return b == null ? List.of() : b; }

    public Bundle bundle(String kind, int level) {
        for (Bundle b : bundles(kind)) if (b.level == level) return b;
        return null;
    }

    /** The ingredient row for (base, item), or null. Base is "WATER" or "AWKWARD". */
    public Ingredient ingredient(String base, String item) {
        if (item == null) return null;
        for (Ingredient i : ingredients) if (i.item.equals(item) && i.base.equals(base)) return i;
        return null;
    }

    public List<Ingredient> ingredientsFor(String effect) {
        List<Ingredient> out = new ArrayList<>();
        for (Ingredient i : ingredients) if (i.effect.equals(effect)) out.add(i);
        return out;
    }

    /** Is this item used at a brewing stand at all (ingredient or modifier)? */
    public boolean isBrewingItem(String item) {
        if (item == null) return false;
        if (modifiers.containsKey(item)) return true;
        for (Ingredient i : ingredients) if (i.item.equals(item)) return true;
        return false;
    }

    /** Item id of a potion: "POTION_SPEED;5" or "SPLASH_POTION_SPEED;5". */
    public static String potionId(String effect, int level, boolean splash) {
        return (splash ? "SPLASH_" : "") + "POTION_" + effect.toUpperCase(java.util.Locale.ROOT) + ";" + level;
    }

    /** Self-consistency check; null when fine. */
    public String validate() {
        if (effects.isEmpty()) return "no effects";
        for (Effect e : effects.values()) {
            if (e.levels.isEmpty()) return e.id + " has no levels";
            if (e.brewMax > e.maxLevel()) return e.id + " brewMax above max level";
            if (e.corruptsTo != null && !effects.containsKey(e.corruptsTo)) return e.id + " corrupts into unknown " + e.corruptsTo;
            for (Level l : e.levels) if (l.seconds < 0) return e.id + " negative duration";
            if (e.splashOnly && e.brewable) return e.id + " is splash-only but brewable";
            if (e.scaled && e.level(1) == null) return e.id + " is scaled but has no level 1 row";
        }
        for (Ingredient i : ingredients) {
            Effect e = effects.get(i.effect);
            if (e == null) return "ingredient " + i.item + " -> unknown effect " + i.effect;
            if (e.level(Math.min(i.level, e.brewMax)) == null) return "ingredient " + i.item + " -> missing level " + i.level;
        }
        for (Map.Entry<String, Integer> g : god.entrySet()) {
            Effect e = effects.get(g.getKey());
            if (e == null) return "god potion lists unknown effect " + g.getKey();
            if (e.level(g.getValue()) == null) return "god potion " + g.getKey() + " level " + g.getValue() + " missing";
        }
        for (List<Bundle> bl : bundles.values()) for (Bundle b : bl) for (Map.Entry<String, Integer> x : b.effects.entrySet()) {
            Effect e = effects.get(x.getKey());
            if (e == null || e.level(x.getValue()) == null) return "bundle " + b.level + " lists bad effect " + x;
        }
        for (BasicBrew b : brews.values()) {
            if (b.effects != null) for (String id : b.effects) if (!effects.containsKey(id)) return "brew " + b.item + " lists unknown effect " + id;
            if (brewsInto(b).isEmpty()) return "brew " + b.item + " boosts no brewable potion";
            if (modifiers.containsKey(b.item)) return "brew " + b.item + " is also a modifier";
            for (Ingredient i : ingredients) if (i.item.equals(b.item)) return "brew " + b.item + " is also an ingredient";
        }
        return null;
    }

    // ---- small text helpers (pure) ------------------------------------------------------------

    private static final String[] ROMAN = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"};

    public static String roman(int n) { return n >= 0 && n < ROMAN.length ? ROMAN[n] : String.valueOf(n); }

    /** 180 -> "3:00", 3725 -> "1:02:05". */
    public static String clock(long seconds) {
        if (seconds < 0) seconds = 0;
        long h = seconds / 3600, m = seconds % 3600 / 60, s = seconds % 60;
        if (h > 0) return h + ":" + (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
        return m + ":" + (s < 10 ? "0" : "") + s;
    }
}
